#!/usr/bin/env node
// gen-slice-registries.mjs — emits the 3 generated registry files from
// slice.json discovery.
//
// Globs `frontend/slices/*/slice.json` (top-level only — slices nested under
// `_templates/` are scaffold sources, not registered). Writes:
//
//   lib/shared/features/registry.generated.ts
//   lib/shared/features/preview-registry.generated.ts
//   lib/shared/features/export-registry.generated.ts
//
// Run: node scripts/features/gen-slice-registries.mjs [--check]
//
// `--check` mode validates that the on-disk generated files match what
// would be written. Used by CI to catch out-of-sync commits.

import { existsSync, readFileSync, readdirSync, statSync, writeFileSync, mkdirSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const REPO = path.resolve(__dirname, "../..");
const SLICES_ROOT = path.join(REPO, "frontend", "slices");
const OUT_DIR = path.join(REPO, "lib", "shared", "features");

const checkMode = process.argv.includes("--check");

const HEADER = `// AUTO-GENERATED by scripts/features/gen-slice-registries.mjs
// DO NOT EDIT — re-run \`node scripts/features/gen-slice-registries.mjs\`
`;

const slices = discoverSlices(SLICES_ROOT);
const sorted = slices.sort((a, b) => a.slug.localeCompare(b.slug));

const outputs = {
  "registry.generated.ts": renderRegistry(sorted),
  "preview-registry.generated.ts": renderPreviewRegistry(sorted),
  "export-registry.generated.ts": renderExportRegistry(sorted),
};

if (checkMode) {
  let drift = 0;
  for (const [name, body] of Object.entries(outputs)) {
    const file = path.join(OUT_DIR, name);
    const onDisk = existsSync(file) ? readFileSync(file, "utf8") : "";
    if (onDisk !== body) {
      console.error(`✖ ${path.relative(REPO, file)} is out of date`);
      drift++;
    }
  }
  if (drift > 0) {
    console.error(`\nRun: node scripts/features/gen-slice-registries.mjs`);
    process.exit(1);
  }
  console.log(`✓ ${slices.length} slice(s) — registries up to date`);
} else {
  mkdirSync(OUT_DIR, { recursive: true });
  for (const [name, body] of Object.entries(outputs)) {
    writeFileSync(path.join(OUT_DIR, name), body);
  }
  console.log(`✓ wrote ${Object.keys(outputs).length} registry file(s) (${slices.length} slice(s))`);
}

// ───────────────────────────────────────────────────────────────────

function discoverSlices(root) {
  if (!existsSync(root)) return [];
  const out = [];
  for (const name of readdirSync(root)) {
    if (name.startsWith("_") || name.startsWith(".")) continue;
    const sliceDir = path.join(root, name);
    if (!statSync(sliceDir).isDirectory()) continue;
    const sj = path.join(sliceDir, "slice.json");
    if (!existsSync(sj)) continue;
    const meta = JSON.parse(readFileSync(sj, "utf8"));
    if (meta.slug !== name) {
      console.warn(`⚠ slice.json slug "${meta.slug}" != folder "${name}" — using folder name`);
    }
    out.push({
      slug: name,
      title: meta.title,
      category: meta.category,
      version: meta.version,
      namespace: meta.namespace,
      configExport: meta.frontend?.configExport,
      registers: meta.registers ?? ["registry"],
      slicePath: meta.frontend?.slicePath ?? `frontend/slices/${name}`,
      providers: meta.providers,
      tablesExport: meta.convex?.tablesExport,
    });
  }
  return out;
}

function renderRegistry(slices) {
  const registered = slices.filter((s) => s.registers.includes("registry"));
  const imports = registered
    .map(
      (s) =>
        `import { ${s.configExport} } from "@/features/${s.slug}/config";`,
    )
    .join("\n");
  const items = registered
    .map(
      (s) => `  {
    ...${s.configExport},
    importPath: "@/features/${s.slug}/config",
    version: ${JSON.stringify(s.version)},
  },`,
    )
    .join("\n");
  return `${HEADER}
import { registerFeatures } from "./registerFeature";
import type { RegisteredSlice } from "./registry";
${imports ? "\n" + imports + "\n" : ""}
export const REGISTERED_SLICES: RegisteredSlice[] = [
${items}
];

registerFeatures(REGISTERED_SLICES);
`;
}

function renderPreviewRegistry(slices) {
  const registered = slices.filter((s) => s.registers.includes("preview-registry"));
  const items = registered
    .map(
      (s) => `  ${JSON.stringify(s.slug)}: () => import("@/features/${s.slug}/page"),`,
    )
    .join("\n");
  return `${HEADER}
import type { ComponentType } from "react";

export const SLICE_PREVIEWS: Record<string, () => Promise<{ default: ComponentType }>> = {
${items}
};
`;
}

function renderExportRegistry(slices) {
  const registered = slices.filter((s) => s.registers.includes("export-registry"));
  const exports = registered
    .filter((s) => s.tablesExport)
    .map(
      (s) =>
        `export { ${s.tablesExport} } from "@convex/features/${s.slug}/schema";`,
    )
    .join("\n");
  return `${HEADER}
// Re-exports of every slice's convex tables fragment so consumers can
// compose their root convex/schema.ts with a single barrel import.
${exports || "// (no slices register an export-registry entry yet)"}
`;
}
